import math

import pytest
from hypothesis import given
import hypothesis.strategies as st

from solution import fib


def ref_fib(n: int) -> int:
    """Obviously-correct reference: iterative definition F0=0, F1=1."""
    assert isinstance(n, int) and n >= 0
    if n == 0:
        return 0
    if n == 1:
        return 1
    a, b = 0, 1
    for _ in range(1, n):
        a, b = b, a + b
    return b


# --- concrete examples from the spec docstring ---
def test_example_fib_10_is_55():
    assert fib(10) == 55


def test_example_fib_1_is_1():
    assert fib(1) == 1


def test_example_fib_8_is_21():
    assert fib(8) == 21


def test_base_cases_match_standard_definition():
    assert fib(0) == 0
    assert fib(1) == 1
    assert fib(2) == 1


def test_return_type_is_int():
    for n in [0, 1, 2, 8, 10]:
        assert isinstance(fib(n), int)


@given(st.integers(min_value=0, max_value=30))
def test_equivalence_to_reference_model(n):
    assert fib(n) == ref_fib(n)


@given(st.integers(min_value=2, max_value=30))
def test_recurrence_relation(n):
    assert fib(n) == fib(n - 1) + fib(n - 2)


@given(st.integers(min_value=0, max_value=30))
def test_sum_identity(n):
    # sum_{i=0..n} F(i) == F(n+2) - 1
    assert sum(fib(i) for i in range(n + 1)) == fib(n + 2) - 1


@given(st.integers(min_value=2, max_value=30))
def test_cassini_identity(n):
    # F(n+1)*F(n-1) - F(n)^2 == (-1)^n
    assert fib(n + 1) * fib(n - 1) - fib(n) * fib(n) == (-1) ** n


@given(st.integers(min_value=2, max_value=30))
def test_monotonic_non_decreasing(n):
    assert fib(n) >= fib(n - 1)
    assert fib(n) >= 1


@given(st.integers(min_value=0, max_value=20), st.integers(min_value=0, max_value=20))
def test_gcd_property(m, n):
    # gcd(F(m), F(n)) == F(gcd(m, n)), with F(0)=0 edge cases handled
    if m == 0 and n == 0:
        return
    if m == 0:
        assert math.gcd(fib(m), fib(n)) == fib(math.gcd(m, n))
        return
    if n == 0:
        assert math.gcd(fib(m), fib(n)) == fib(math.gcd(m, n))
        return
    assert math.gcd(fib(m), fib(n)) == fib(math.gcd(m, n))


@given(st.integers(min_value=0, max_value=25))
def test_doubling_identities(n):
    # F(2n) == F(n) * (2*F(n+1) - F(n))
    # F(2n+1) == F(n+1)^2 + F(n)^2
    assert fib(2 * n) == fib(n) * (2 * fib(n + 1) - fib(n))
    assert fib(2 * n + 1) == fib(n + 1) ** 2 + fib(n) ** 2
